"kind": "propose",
"summary": "The current revision's memory limit is insufficient, causing OOM kills. Increasing the memory limit to 768Mi addresses this.",
"hypotheses": [
  {
    "root_cause_class": "memory_limit_too_low",
    "summary": "Containers are OOMKilled despite peaking at 100% of their 512Mi limit, indicating the limit is insufficient.",
    "supporting": ["oom_killed_current_revision", "memory_at_limit_before_kill", "memory_data_available"],
