],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "catalog",
    "uid": "uid-deployment-catalog"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "memory": "768Mi"
        }
      }
    }
  },
  "expected_effect": "The memory limit increase should prevent OOMKilled errors by providing sufficient headroom for peak usage.",
  "rationale": "The container consistently peaked at 100% of its 512Mi limit, triggering OOM kills. Raising the limit to 768Mi (1.5× current) addresses this without requiring rollback, as earlier revisions lack active pods for comparison.",
  "cited_evidence_ids": ["ev-container_memory", "ev-rollout_history", "ev-pod_states"],
  "cited_predicates": ["oom_killed_current_revision", "memory_at_limit_before_kill", "memory_data_available"]
}
